import fs from 'node:fs';import crypto from 'node:crypto';import {chromium} from '/validator/node_modules/playwright/index.mjs';
const html=fs.readFileSync('/input/game.html','utf8'),browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_EXECUTABLE,args:['--no-sandbox','--disable-dev-shm-usage']});const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true});await context.tracing.start({screenshots:true,snapshots:true});const page=await context.newPage();await context.route('**/*',route=>route.request().url()==='http://game.invalid/'?route.fulfill({contentType:'text/html',body:html}):route.abort());await page.goto('http://game.invalid/');
const tap=async selector=>{const box=await page.locator(selector).boundingBox();await page.touchscreen.tap(box.x+box.width/2,box.y+box.height/2);};await tap('#p2p-start');await tap('#move-0');await tap('#move-1');const before=await page.evaluate(()=>({scroll:scrollY,snapshot:window.__GAME_TEST__.snapshot()}));const boxBefore=await page.locator('#move-2').boundingBox();const session=await context.newCDPSession(page);await session.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:195,y:650}]});for(let i=1;i<=10;i++){await session.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:195,y:650-500*i/10}]});await page.waitForTimeout(20);}await session.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await page.waitForTimeout(500);const after=await page.evaluate(()=>({scroll:scrollY,snapshot:window.__GAME_TEST__.snapshot()}));const boxAfter=await page.locator('#move-2').boundingBox();await tap('#move-2');const final=await page.evaluate(()=>window.__GAME_TEST__.snapshot());fs.writeFileSync('/evidence/dense-final.png',await page.screenshot());await context.tracing.stop({path:'/evidence/dense-trace.zip'});process.stdout.write(JSON.stringify({scope:'Actual coordinate touch pan on a normal button, followed by a reached below-fold control. Reviewed fixture only; no candidate/source edits.',browser_version:browser.version(),html_sha256:crypto.createHash('sha256').update(html).digest('hex'),before,boxBefore,after,boxAfter,final,pan_changed_document:after.scroll>before.scroll,pan_did_not_click:JSON.stringify(after.snapshot)===JSON.stringify(before.snapshot),ordinary_input_won:final.phase==='won'}));await browser.close();
